// Catalog data source.
//
// In a real deployment getAllProducts() would read from the local catalog
// store (the post-sync copy) and syncCatalogFromErp() would pull pricing,
// inventory, and availability from the upstream ERP/PIM. Both are simulated
// here. The module-level `revision` / `syncedAt` state lets the page show
// whether it is rendering stale or freshly synced data.

let revision = 0
let syncedAt = '2024-01-01T00:00:00.000Z'

// Simulate an expensive upstream ERP/PIM pull across thousands of SKUs.
// This is the slow work we deliberately defer to the background so the admin's
// request never blocks on it.
export async function syncCatalogFromErp() {
  await new Promise((resolve) => setTimeout(resolve, 1500))
  revision += 1
  syncedAt = new Date().toISOString()
}

// Simulate a read from the local catalog store. Cheap once warm; the expensive
// upstream work lives in syncCatalogFromErp() above.
export async function getAllProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))

  return [
    { id: 1, name: 'Laptop', price: 999, inStock: true },
    { id: 2, name: 'Phone', price: 699, inStock: true },
    { id: 3, name: 'Tablet', price: 499, inStock: false },
    { id: 4, name: 'Headphones', price: 199, inStock: true },
    { id: 5, name: 'Watch', price: 299, inStock: true },
  ].map((product) => ({ ...product, revision, syncedAt }))
}

import { unstable_cache } from 'next/cache'

import { getAllProducts } from './db'

export type Product = {
  id: number
  name: string
  price: number
  inStock: boolean
  revision: number
  syncedAt: string
}

export type Catalog = {
  products: Product[]
  revision: number
  syncedAt: string
  fetchedAt: string
}

// Cache the catalog read under the shared "products" tag.
//
// - keyParts: ['products'] -> one warm cache entry shared by every catalog view.
// - tags: ['products']      -> a single revalidateTag('products') invalidates it
//                              (and every other consumer of the same tag) at once.
// - revalidate: false       -> stay warm until an admin sync explicitly
//                              invalidates it, so day-to-day browsing never
//                              re-queries the catalog.
export const getCatalog = unstable_cache(
  async (): Promise<Catalog> => {
    const products = (await getAllProducts()) as Product[]
    return {
      products,
      revision: products[0]?.revision ?? 0,
      syncedAt: products[0]?.syncedAt ?? '',
      fetchedAt: new Date().toISOString(),
    }
  },
  ['products'],
  { tags: ['products'], revalidate: false }
)

import { revalidateTag } from 'next/cache'
import { redirect } from 'next/navigation'
import { after } from 'next/server'

import { getCatalog, type Product } from '@/lib/catalog'
import { syncCatalogFromErp } from '@/lib/db'

// Inline Server Action backing the "Sync latest catalog" form.
//
// The slow upstream ERP/PIM pull runs inside after(), i.e. *after* this response
// is sent, so the admin can keep working immediately and the list is only
// briefly stale. Once the pull finishes we revalidateTag('products'), which
// invalidates the shared catalog cache (and every view that depends on it) so
// they all converge on the fresh data shortly after.
async function syncCatalogAction() {
  'use server'
  after(async () => {
    await syncCatalogFromErp()
    revalidateTag('products')
  })
  redirect('/admin/catalog')
}

const money = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
})

export default async function CatalogPage() {
  const { products, revision, syncedAt, fetchedAt } = await getCatalog()

  return (
    <main
      style={{
        fontFamily: 'system-ui, sans-serif',
        maxWidth: 960,
        margin: '0 auto',
        padding: 24,
      }}
    >
      <header
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'flex-start',
          gap: 16,
        }}
      >
        <div>
          <h1 style={{ margin: 0 }}>Product Catalog</h1>
          <p style={{ color: '#666', margin: '4px 0 0' }}>
            Revision {revision} &middot; synced {syncedAt} &middot; cache fetched{' '}
            {fetchedAt}
          </p>
        </div>
        <form action={syncCatalogAction}>
          <button type="submit">Sync latest catalog</button>
        </form>
      </header>

      <p style={{ color: '#666' }}>
        Submitting pulls pricing, inventory, and availability from the upstream
        ERP/PIM. You can keep working immediately &mdash; the catalog refreshes in
        the background and updates here, and across every view that shares the
        same catalog cache, shortly after.
      </p>

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: 16 }}>
        <thead>
          <tr style={{ textAlign: 'left', borderBottom: '2px solid #eee' }}>
            <th style={{ padding: 8 }}>SKU</th>
            <th style={{ padding: 8 }}>Name</th>
            <th style={{ padding: 8 }}>Price</th>
            <th style={{ padding: 8 }}>Availability</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product: Product) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #eee' }}>
              <td style={{ padding: 8 }}>#{product.id}</td>
              <td style={{ padding: 8 }}>{product.name}</td>
              <td style={{ padding: 8 }}>{money.format(product.price)}</td>
              <td style={{ padding: 8 }}>
                {product.inStock ? 'In stock' : 'Out of stock'}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

